sys_script.script:
(function executeRule(current, previous) {

    try {
        var participantAssignmentSysId = current.getValue('participant_assignment');

        // No Participant Assignment attached → allow update
        if (!participantAssignmentSysId)
            return;

        var participantGR = new GlideRecordSecure('x_ctans_incentnow_participant_assignment');

        if (!participantGR.get(participantAssignmentSysId)) {
            gs.addErrorMessage('The related Participant Assignment could not be found.');
            current.setAbortAction(true);
            return;
        }

        // Update allowed only while Participant Assignment is Draft
        if (participantGR.getValue('status') != 'draft') {
            gs.addErrorMessage('Plan Assignment cannot be updated because the related Participant Assignment is not in Draft state.');
            current.setAbortAction(true);
        }

    } catch (e) {
        gs.error('[IncentIQ Plan Assignment] Update validation failed. Plan Assignment=' +
            current.getUniqueValue() + ', Error=' + e.message);

        gs.addErrorMessage('Plan Assignment could not be updated because validation failed.');
        current.setAbortAction(true);
    }

})(current, previous);
